mapper.update:
update conversation
set last_message = #{lastMessage}, last_message_time = #{lastMessageTime}
where id = #{conversationId}

update conversation_user
set unread_count = greatest(unread_count - #{markedCount}, 0),
    last_read_message_id = #{lastMessageId}
where conversation_id = #{conversationId} and user_id = #{userId}
  and (last_read_message_id is null or last_read_message_id < #{lastMessageId})

mapper.select:
select unread_count
from conversation_user
where user_id = #{UserId} and unread_count != 0;

select *
from private_message
where sender_id = #{senderId}
  and client_message_id = #{clientMessageId}
limit 1

select *
from private_message
where sender_id = #{senderId}
  and client_message_id = #{clientMessageId}
limit 1
for update
